// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, address target, uint256 value) public {
        // Bound value to avoid overflow and ensure non-zero
        vm.assume(value > 0 && value <= address(this).balance);
        // Ensure nonOwner is not the contract owner
        vm.assume(nonOwner != c.owner());
        // Ensure target is not the zero address (to avoid burn in some cases, but not strictly needed)
        vm.assume(target != address(0));

        // Fund the contract with enough balance to potentially send
        vm.deal(address(c), value);

        // Attempt to call sendMoney as nonOwner; it should revert
        vm.prank(nonOwner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));
        assertTrue(!success, "Non-owner should not be able to send money");
    }
}

